execute-script.function:
t -> e -> {
    values = $t.get(`ehome.operational:EnumerationType#values`);
    last = $values.map(v -> $v.get(`ehome.operational:EnumerationValue#value`)).max();
    $e.set(`ehome.operational:EnumerationValue#value`, if($last == null, 0, $last + 1));
    $e.set(`ehome.operational:EnumerationValue#index`, $values.size());
    $e
}
